"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["93983"],{947051(n){n.exports=JSON.parse('{"id":8452,"title":"1000\u8BCD-U1 B","description":"**\u6574\u4F53\u98CE\u683C\uFF1A** \u6E29\u6696\u53CB\u597D\u3001\u624B\u7ED8\u8D28\u611F\u7684\u5361\u901A\u98CE\u683C\uFF0C\u80CC\u666F\u4E3A\u6D45\u5976\u6CB9\u8272\u3002\\n**\u6838\u5FC3\u89D2\u8272\uFF1A** \u6731\u8FEA\xb7\u970D\u666E\u65AF\uFF08Judy\uFF09\u548C\u5C3C\u514B\xb7\u738B\u5C14\u5FB7\uFF08Nick\uFF09\uFF0C\u4ED6\u4EEC\u4F5C\u4E3A\u201C\u5C0F\u8001\u5E08\u201D\u5F15\u5BFC\u5B66\u4E60\u3002\\n**\u5E03\u5C40\uFF1A** \u4ECE\u4E0A\u5230\u4E0B\u6E05\u6670\u7684\u4E09\u4E2A\u6A21\u5757\u3002\\n\\n---\\n\\n#### **\u6A21\u5757 1\uFF1A\u9876\u90E8\u8BCD\u6C47\u7F51\u683C (3x4 Grid)**\\n**\u6807\u9898 (\u53CC\u8BED)\uFF1A** \u4ECA\u65E5\u8BCD\u6C47 / Today\'s Words\\n*   **\u5E03\u5C40\uFF1A** 3\u884C x 4\u5217\uFF08\u6700\u540E\u4E00\u4E2A\u683C\u5B50\u653E\u89D2\u8272\u5C0F\u63D2\u56FE\uFF09\u3002\u6BCF\u4E2A\u683C\u5B50\u80CC\u666F\u4E3A\u67D4\u548C\u7684\u5706\u89D2\u77E9\u5F62\uFF0C\u989C\u8272\u5404\u5F02\uFF08\u6DE1\u84DD\u3001\u6DE1\u7C89\u3001\u6DE1\u9EC4\u3001\u6DE1\u7EFF\u7B49\uFF09\u3002\\n*   **\u5185\u5BB9 (\u6BCF\u4E2A\u683C\u5B50\u5185\u4ECE\u4E0A\u5230\u4E0B)\uFF1A**\\n    1.  **big** - \u5927\u7684\\n    2.  **boy** - \u7537\u5B69\\n    3.  **child** - \u5C0F\u5B69\\n    4.  **have** - \u6709\\n    5.  **loud** - \u5927\u58F0\u7684\\n    6.  **story** - \u6545\u4E8B\\n    7.  **swim** - \u6E38\u6CF3\\n    8.  **today** - \u4ECA\u5929\\n    9.  **watch** - \u89C2\u770B\\n    10. **worry** - \u62C5\u5FC3\\n    *   **\u7B2C11\u683C (\u53F3\u4E0B\u89D2)\uFF1A** \u4E00\u4E2A\u5C0F\u63D2\u56FE\uFF0C\u753B\u7740\u6731\u8FEA\u62FF\u7740\u5199\u5B57\u677F\uFF0C\u5C3C\u514B\u60A0\u95F2\u5730\u9760\u5728\u65C1\u8FB9\uFF0C\u65C1\u8FB9\u5199\u7740\u201C\u548C\u6731\u8FEA\u5C3C\u514B\u4E00\u8D77\u5B66\uFF01\u201D\u3002\\n\\n---\\n\\n#### **\u6A21\u5757 2\uFF1A\u4E2D\u90E8\u5BF9\u8BDD\u8FDE\u73AF\u6F2B\u753B (3\u4E2A\u753B\u683C)**\\n**\u6807\u9898 (\u53CC\u8BED)\uFF1A** \u770B\u770B\u4ED6\u4EEC\u5728\u8BF4\u4EC0\u4E48\uFF1F / Let\'s See What They\'re Saying!\\n**\u6545\u4E8B\u4E32\u8054\uFF1A** \u4E00\u4E2A\u5173\u4E8E\u5C3C\u514B\u201C\u62C5\u5FC3\u201D\u5C0F\u7537\u5B69\u7684\u6545\u4E8B\u3002\\n\\n*   **\u753B\u683C 1 (\u5DE6)\uFF1A**\\n    *   **\u573A\u666F\uFF1A** \u6731\u8FEA\u548C\u5C3C\u514B\u7AD9\u5728\u6E38\u6CF3\u6C60\u8FB9\u3002\u4E00\u4E2A\u5C0F\u7537\u5B69 (**child/boy**) \u6B63\u51C6\u5907\u4E0B\u6C34\u3002\\n    *   **\u5C3C\u514B (\u62C5\u5FE7\u72B6)\uFF1A** \u201CThat **boy** wants to **swim**. He is so small, but the pool looks **big**.\u201D (\u90A3\u4E2A**\u7537\u5B69**\u60F3\u53BB**\u6E38\u6CF3**\u3002\u4ED6\u8FD9\u4E48\u5C0F\uFF0C\u4F46\u6C60\u5B50\u770B\u8D77\u6765\u5F88**\u5927**\u3002)\\n*   **\u753B\u683C 2 (\u4E2D)\uFF1A**\\n    *   **\u573A\u666F\uFF1A** \u5C0F\u7537\u5B69\u5728\u5F00\u5FC3\u5730\u6E38\u6CF3\uFF0C\u5C3C\u514B\u5728\u4E00\u65C1\u7D27\u5F20\u5730\u770B\u7740(**watch**)\u3002\\n    *   **\u6731\u8FEA (\u7B11\u7740\u5BF9\u5C3C\u514B\u8BF4)\uFF1A** \u201CDon\'t **worry**, Nick! He **has** a float ring. Let\'s **watch** him.\u201D (\u522B**\u62C5\u5FC3**\uFF0C\u5C3C\u514B\uFF01\u4ED6**\u6709**\u6E38\u6CF3\u5708\u3002\u6211\u4EEC**\u770B\u770B**\u4ED6\u5427\u3002)\\n*   **\u753B\u683C 3 (\u53F3)\uFF1A**\\n    *   **\u573A\u666F\uFF1A** \u6CF3\u6C60\u8FB9\uFF0C\u5C0F\u7537\u5B69\u6E38\u5B8C\u6CF3\uFF0C\u6B63\u5174\u594B\u5730\u8DDF\u6731\u8FEA\u548C\u5C3C\u514B\u8BF4\u8BDD\u3002\\n    *   **\u5C0F\u7537\u5B69 (\u5174\u594B\u5730\uFF0C\u8868\u60C5\u53EF\u4EE5\u753B\u5F97**loud**\u4E00\u4E9B)\uFF1A** \u201C**Today** is fun! I can **swim**! Can I hear a **story**?\u201D (**\u4ECA\u5929**\u771F\u597D\u73A9\uFF01\u6211\u4F1A**\u6E38\u6CF3**\u4E86\uFF01\u80FD\u7ED9\u6211\u8BB2\u4E2A**\u6545\u4E8B**\u5417\uFF1F)\\n    *   **\u5C3C\u514B (\u64E6\u6C57\uFF0C\u5982\u91CA\u91CD\u8D1F)\uFF1A** \u201CA **story**? Okay, but not a **loud** one.\u201D (\u8BB2**\u6545\u4E8B**\uFF1F\u597D\u5427\uFF0C\u4F46\u522B\u8BB2\u592A**\u5927\u58F0**\u7684\u3002)\\n\\n---\\n\\n#### **\u6A21\u5757 3\uFF1A\u5E95\u90E8\u5199\u4F5C\u7EC3\u4E60**\\n**\u6807\u9898 (\u53CC\u8BED)\uFF1A** \u4E00\u8D77\u6765\u586B\u7A7A\uFF01 / Let\'s Fill in the Blanks!\\n\\n**\u8BF4\u660E\u6587\u5B57\uFF1A** \u8BF7\u7528\u4E0A\u65B9\u8BCD\u6C47\u7F51\u683C\u4E2D\u7684\u5355\u8BCD\u586B\u7A7A\uFF0C\u5B8C\u6210\u53E5\u5B50\u3002\u6BCF\u8BCD\u53EA\u7528\u4E00\u6B21\u3002\\nUse the words from the grid to complete the sentences. Use each word only once.\\n\\n**\u7EC3\u4E60\u9898 (\u7559\u51FA\u4E0B\u5212\u7EBF\u4F5C\u4E3A\u7A7A\u767D)\uFF1A**\\n\\n1.  I am a **child**. I am a **boy**.\\n    (\u6211\u662F\u4E00\u4E2A**\u5C0F\u5B69**\u3002\u6211\u662F\u4E00\u4E2A**\u7537\u5B69**\u3002)\\n2.  **Today**, I **have** a new book.\\n    (**\u4ECA\u5929**\uFF0C\u6211**\u6709**\u4E00\u672C\u65B0\u4E66\u3002)\\n3.  I like to **watch** my friend **swim**.\\n    (\u6211\u559C\u6B22**\u89C2\u770B**\u6211\u7684\u670B\u53CB**\u6E38\u6CF3**\u3002)\\n4.  Please read me a **story**.\\n    (\u8BF7\u7ED9\u6211\u8BFB\u4E00\u4E2A**\u6545\u4E8B**\u3002)\\n5.  The elephant is very **big**.\\n    (\u8FD9\u5934\u5927\u8C61\u975E\u5E38**\u5927**\u3002)\\n6.  Do not **worry**. Do not be too **loud**.\\n    (\u522B**\u62C5\u5FC3**\u3002\u522B\u592A**\u5927\u58F0**\u3002)\\n","remark":"\u505A\u6210\u56FE\u7247","owner":"hhs","upvotes":5,"downvotes":0,"upvoteDifference":5,"updatedAt":"2026-04-13T20:38:50.346Z"}')}}]);